 void settings(){LinearLayout box=column();box.setPadding(dp(22),dp(8),dp(22),dp(8));box.addView(label("Для приватных проектов нужен GitHub Personal Access Token. Создай fine-grained token для своих репозиториев: Metadata — Read-only, Pages — Read-only. Выбери все нужные репозитории.\nТокен хранится зашифрованным только на телефоне и отправляется только api.github.com.",14,white));Button help=button("Создать токен в GitHub ↗");help.setOnClickListener(v->open("https://github.com/settings/personal-access-tokens/new"));box.addView(help);EditText input=new EditText(this);input.setTextColor(white);input.setHintTextColor(muted);input.setHint("Вставь токен GitHub");input.setSingleLine();input.setInputType(129);box.addView(input);AlertDialog d=new AlertDialog.Builder(this).setTitle("Подключение GitHub").setView(box).setPositiveButton("Сохранить",null).setNeutralButton("Отключить",(a,b)->{try{saveToken("");prefs().edit().remove("repos").apply();repos=new JSONArray();render();sync();}catch(Exception e){status.setText("Не удалось удалить подключение");}}).setNegativeButton("Отмена",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String t=input.getText().toString().trim();if(t.isEmpty()){input.setError("Вставь токен или нажми «Отключить»");return;}try{saveToken(t);d.dismiss();sync();}catch(Exception e){input.setError("Не удалось сохранить токен");}}));d.show();}
 String request(String path,String t)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://api.github.com"+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("X-GitHub-Api-Version","2022-11-28");c.setRequestProperty("User-Agent","Nicolenkoe-Project-Hub/1.0");if(!t.isEmpty())c.setRequestProperty("Authorization","Bearer "+t);try{int code=c.getResponseCode();if(code!=200)throw new IOException("HTTP "+code);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}finally{c.disconnect();}}
 void sync(){if(busy)return;busy=true;refresh.setEnabled(false);status.setText("Обновляю репозитории и сайты…");executor.execute(()->{try{String t=token();JSONArray result=new JSONArray();for(int page=1;;page++){String endpoint=t.isEmpty()?"/users/nicolenkoe/repos?per_page=100&page=":"/user/repos?affiliation=owner&per_page=100&page=";JSONArray batch=new JSONArray(request(endpoint+page,t));for(int i=0;i<batch.length();i++){JSONObject r=batch.getJSONObject(i);if(!r.getJSONObject("owner").optString("login").equalsIgnoreCase("nicolenkoe"))continue;JSONObject p=new JSONObject();p.put("name",r.getString("name"));p.put("private",r.optBoolean("private"));p.put("html_url",r.getString("html_url"));String site="";if(r.optBoolean("has_pages")){String full=r.getString("full_name");try{site=new JSONObject(request("/repos/"+full+"/pages",t)).optString("html_url");}catch(Exception e){}if(site.isEmpty())site="https://nicolenkoe.github.io/"+(r.getString("name").equalsIgnoreCase("nicolenkoe.github.io")?"":Uri.encode(r.getString("name"))+"/");}p.put("site",site);result.put(p);}if(batch.length()<100)break;}JSONObject self=new JSONObject();self.put("name","my-projects");self.put("private",false);self.put("html_url","https://github.com/nicolenkoe/fragment-logo-editor/tree/gh-pages/my-projects");self.put("site","https://nicolenkoe.github.io/fragment-logo-editor/my-projects/");result.put(self);String stamp=java.text.DateFormat.getDateTimeInstance(3,3).format(new java.util.Date());prefs().edit().putString("repos",result.toString()).putString("updated",stamp).apply();runOnUiThread(()->{repos=result;render();status.setText("Обновлено: "+stamp+" · "+result.length()+" проектов"+(t.isEmpty()?"\nДля приватных нажми GitHub ⚙":"\nПриватные — в пределах доступа токена"));});}catch(Exception e){String message=e.getMessage();final String info=message!=null&&message.contains("401")?"Токен недействителен. Открой GitHub ⚙":message!=null&&message.contains("403")?"GitHub ограничил доступ или число запросов. Проверь права токена или повтори позже.":"Не удалось обновить. Проверь интернет и подключение GitHub.";runOnUiThread(()->status.setText(info+"\nСохранённый список: "+prefs().getString("updated","пока отсутствует")));}finally{runOnUiThread(()->{busy=false;refresh.setEnabled(true);});}});}
